css:
.print-format {
    font-family: "Helvetica Neue", Arial, sans-serif;
    font-size: 12px;
    color: #333;
    padding: 20px;
}

.header {
    text-align: center;
    margin-bottom: 25px;
}

.header h2 {
    margin: 0;
    font-size: 28px;
    color: #1f2937;
}

.header p {
    margin-top: 5px;
    color: #6b7280;
    font-size: 14px;
}

.member-box {
    border: 1px solid #d1d5db;
    border-radius: 6px;
    overflow: hidden;
    width: 100%;
}

.member-box .title {
    background: #1f4e79;
    color: white;
    padding: 10px 15px;
    font-size: 16px;
    font-weight: bold;
}

.info-table {
    width: 100%;
    border-collapse: collapse;
}

.info-table td {
    padding: 10px 15px;
    border-bottom: 1px solid #e5e7eb;
}

.info-table tr:last-child td {
    border-bottom: none;
}

.label {
    width: 35%;
    background: #f8f9fa;
    font-weight: 600;
    color: #374151;
}

.value {
    width: 85%;
}

.footer {
    margin-top: 40px;
    text-align: right;
    font-size: 11px;
    color: #888;
}
